head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > P > maxByteLength]<br/>SearchBox 컴포넌트에 입력 가능한 최대 바이트 길이를 설정합니다.",
    "validation" : [
        "validate() 메소드로 유효성 체크 실행 시 입력값의 Byte 수가 설정값보다 크면 유효성 체크는 실패로 처리됩니다.",
        "유효성 체크 실패 시 displaymessage='true' 이면 시스템 기본 메시지 'n byte를 초과하여 입력할 수 없습니다.' 가 출력됩니다.",
        "유효성 체크 실패 메시지는 invalidMessage 속성으로 변경할 수 있습니다.",
        "유효성 체크 실패 메시지는 invalidMessageFunc 속성으로 변경할 수 있습니다.",
        "displaymessage='false' 이면 유효성 체크 실패 시 메시지를 출력하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


scwin.fn_invalidMessageFunc = function () {
    var type = this.getType();
    if (type === "maxByteLength")
        return "invalidMessageFunc : 최대 byte 를 초과하여 입력할 수 없습니다.";
    return "Not valid.";
};


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}

// target1 : displaymessage=true, maxByteLength=6 / 입력값=가나다라 (8byte) → 기본 메시지 alert
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("가나다라");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}

// target2 : displaymessage=true, invalidMessage, maxByteLength=6 / 입력값=가나다라 → invalidMessage alert
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나다라");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}

// target3 : displaymessage=true, invalidMessageFunc, maxByteLength=6 / 입력값=가나다라 → 함수 반환 메시지 alert
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("가나다라");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.btn_setValue3_onclick();
    scwin.check_validate(target3);
}

// target4 : displaymessage=false, invalidMessage, maxByteLength=6 / 입력값=가나다라 → 메시지 미출력
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("가나다라");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.btn_setValue4_onclick();
    scwin.check_validate(target4);
}
